62	  // --- build_argv: every placeholder filled, including substring + repeat ---
63	  {
64	    std::string err;
65	    std::map<std::string, std::string> ctx = {
66	        {"bin", "/q"},      {"elf", "/e"},     {"plugin", "/p"},
67	        {"mmap", "/m"},     {"mmap_size", "134217728"}, {"state_out", "/s0"},
68	        {"trigger", ""},  // marker: no plugin suffix
69	        {"vlen", "512"},
70	    };
71	    std::vector<std::string> got = build_argv(kQemuFastLeg, ctx, err);
72	    CHECK(err.empty());
73	    check_eq(got,
74	             {"/q", "-object",
75	              "memory-backend-file,id=mem,share=on,mem-path=/m,size=134217728",
76	              "-machine", "andes_ae350,memory-backend=mem", "-cpu",
77	              "andes-ax45mpv,vlen=512", "-nographic", "-semihosting-config",
78	              "enable=on,target=native", "-bios", "/e", "-plugin",
79	              "/p,outfile=/s0"},
80	             "qemu");
81	  }
82	  {
83	    std::string err;
84	    std::map<std::string, std::string> ctx = {
85	        {"bin", "/v"},  {"elf", "/e"},  {"state_in", "/s0"},
86	        {"state_out", "/s1"}, {"mmap", "/m"}, {"mmap_size", "134217728"},
87	        {"mmap_base", "0x0"},
88	    };
89	    std::vector<std::string> got = build_argv(kVsimAccurateLeg, ctx, err);
90	    CHECK(err.empty());
91	    check_eq(got,
92	             {"/v", "/e", "--resume-from-qemu", "/s0", "--handoff-out", "/s1",
93	              "--shared-mem-path", "/m", "--shared-mem-size", "134217728",
94	              "--shared-mem-base", "0x0"},
95	             "vsim");
96	  }
97	  // a repeated placeholder expands every occurrence
98	  {
99	    std::string err;
100	    std::vector<std::string> got =
101	        build_argv({"a={x},b={y},a2={x}"}, {{"x", "1"}, {"y", "2"}}, err);
102	    CHECK(err.empty());
103	    check_eq(got, {"a=1,b=2,a2=1"}, "repeat");
104	  }
105	  // an unknown placeholder is an error, not a silent empty fill
106	  {
107	    std::string err;
108	    std::vector<std::string> got = build_argv({"{bogus}"}, {{"x", "1"}}, err);
109	    CHECK(got.empty());
110	    CHECK(!err.empty());
111	  }
112	
113	  // --- plan_argvs: thread state files across a 2-step hybrid plan ---
114	  std::vector<EngineDescriptor> engines = {
115	      fake("qemu", "/qbin", "fast-leg", kQemuFastLeg),
116	      fake("vsim:test", "/vbin", "accurate-leg", kVsimAccurateLeg),
117	  };
118	  Plan plan;
119	  plan.elf = "/e";
120	  plan.mem_size = 134217728;
121	  plan.steps = {
122	      {"qemu", "fast-leg", {"marker", {}}},
123	      {"vsim:test", "accurate-leg", {"marker", {}}},
124	  };
125	  RuntimeCtx rc;
126	  rc.mmap_path = "/mm";
127	  rc.mem_size = 134217728;
128	  rc.mmap_base = "0x0";
129	  rc.plugin_path = "/pl";
130	
131	  {
132	    std::string err;
133	    std::vector<std::vector<std::string>> argvs =
134	        plan_argvs(plan, engines, "/wd", rc, err);
135	    CHECK(err.empty());
136	    CHECK(argvs.size() == 2);
137	    if (argvs.size() == 2) {
138	      // step 0 (qemu): drains to state-0.bin; no state_in referenced
139	      check_eq(argvs[0],
140	               {"/qbin", "-object",
141	                "memory-backend-file,id=mem,share=on,mem-path=/mm,size=134217728",
142	                "-machine", "andes_ae350,memory-backend=mem", "-cpu",
143	                "andes-ax45mpv,vlen=512", "-nographic", "-semihosting-config",
144	                "enable=on,target=native", "-bios", "/e", "-plugin",
145	                "/pl,outfile=/wd/state-0.bin"},
146	               "step0");
147	      // step 1 (vsim): resumes from step 0's drain, drains to state-1.bin
148	      check_eq(argvs[1],
149	               {"/vbin", "/e", "--resume-from-qemu", "/wd/state-0.bin",
150	                "--handoff-out", "/wd/state-1.bin", "--shared-mem-path", "/mm",
151	                "--shared-mem-size", "134217728", "--shared-mem-base", "0x0"},
152	               "step1");
153	    }
154	  }
155	  // --- plan_argvs: the fast leg inherits the accurate-leg engine's vlen ---
156	  // (hw-config sync: the engine descriptor's vlen fills {vlen} in the QEMU
157	  // -cpu template; an engine that reports none falls back to 512 -- covered
158	  // by the default plan above, whose vsim:test has no vlen.)
159	  {
160	    std::vector<EngineDescriptor> engines128 = engines;
161	    engines128[1].vlen = 128;  // e.g. vsim:ax66_makatau
162	    std::string err;
163	    std::vector<std::vector<std::string>> argvs =
164	        plan_argvs(plan, engines128, "/wd", rc, err);
165	    CHECK(err.empty());
166	    CHECK(argvs.size() == 2);
167	    if (argvs.size() == 2) {
168	      bool found = false;
169	      for (const std::string& a : argvs[0])
170	        if (a == "andes-ax45mpv,vlen=128") found = true;
171	      CHECK(found);
172	    }
173	  }
174	
175	  // --- plan_argvs: LM content transport wiring (ROADMAP_ilm_dlm F3) ---
176	  // When the accurate-leg engine reports local memories (ilm_size/dlm_size,
177	  // bytes), the fast (QEMU) leg's plugin token grows the sidecar-drain args
178	  // and the vsim leg gets --ilm/--dlm pointing at the sidecars next to its
179	  // state_in. The no-LM case (sizes 0) is already locked by the exact
180	  // check_eq on step0/step1 above: no ilm/dlm token anywhere.
181	  {
182	    std::vector<EngineDescriptor> lm = engines;
183	    lm[1].ilm_size = 65536;
184	    lm[1].dlm_size = 32768;
185	    std::string err;
186	    std::vector<std::vector<std::string>> argvs =
187	        plan_argvs(plan, lm, "/wd", rc, err);
188	    CHECK(err.empty());
189	    CHECK(argvs.size() == 2);
190	    if (argvs.size() == 2) {
191	      bool plugin_has_lm = false;
192	      for (const std::string& a : argvs[0])
193	        if (a == "/pl,outfile=/wd/state-0.bin,ilm_size=65536,dlm_size=32768")
194	          plugin_has_lm = true;
195	      CHECK(plugin_has_lm);
196	      bool has_ilm = false, has_dlm = false;
197	      for (size_t k = 0; k + 1 < argvs[1].size(); ++k) {
198	        if (argvs[1][k] == "--ilm" && argvs[1][k + 1] == "/wd/state-0.bin.ilm")
199	          has_ilm = true;
200	        if (argvs[1][k] == "--dlm" && argvs[1][k + 1] == "/wd/state-0.bin.dlm")
201	          has_dlm = true;
202	      }
203	      CHECK(has_ilm);
204	      CHECK(has_dlm);
205	    }
206	  }
207	  // ILM-only engine: each memory gates independently, no --dlm anywhere
208	  {
209	    std::vector<EngineDescriptor> lm = engines;
210	    lm[1].ilm_size = 65536;  // dlm_size stays 0
211	    std::string err;
212	    std::vector<std::vector<std::string>> argvs =
213	        plan_argvs(plan, lm, "/wd", rc, err);
214	    CHECK(err.empty());
215	    if (argvs.size() == 2) {
216	      bool plugin_has = false;
217	      for (const std::string& a : argvs[0])
218	        if (a == "/pl,outfile=/wd/state-0.bin,ilm_size=65536") plugin_has = true;
219	      CHECK(plugin_has);
220	      for (const std::string& a : argvs[1]) CHECK(a != "--dlm");
221	    }
222	  }
223	
224	  // --- render_argv: a shell-quoted, copy-pasteable command line ---
225	  // Safe tokens (qemu's comma/equals args, paths) pass through untouched;
226	  // empty, spaces, and quotes get POSIX single-quoting so the line is runnable.
227	  {
228	    CHECK(render_argv({"qemu", "-cpu", "andes-ax45mpv,vlen=512"}) ==
229	          "qemu -cpu andes-ax45mpv,vlen=512");
230	    CHECK(render_argv({"-object",
231	                       "memory-backend-file,id=mem,mem-path=/m,size=134217728"}) ==
232	          "-object memory-backend-file,id=mem,mem-path=/m,size=134217728");
233	    CHECK(render_argv({"-readconfig", "/tmp/a b/qemu.cfg"}) ==
234	          "-readconfig '/tmp/a b/qemu.cfg'");
235	    CHECK(render_argv({"x", ""}) == "x ''");
236	    CHECK(render_argv({"it's"}) == "'it'\\''s'");
237	  }
238	
239	  // --- stage_qemu_cfg: a clean probe writes the cfg; a failed probe falls back ---
240	  // The accurate engine's `--print-qemu-config` stdout becomes workdir/qemu.cfg;
241	  // any probe failure (engine lacks the flag -> non-zero exit, timeout, empty)
242	  // yields "" so the fast leg keeps its default -cpu.
243	  {
244	    namespace fs = std::filesystem;
245	    const fs::path dir = fs::temp_directory_path() / "andesim-fa2-stage";
246	    fs::remove_all(dir);
247	    fs::create_directories(dir);
248	
249	    RunResult ok;
250	    ok.rc = 0;
251	    ok.out = "[global]\ndriver = \"andes-ax45mpv-riscv-cpu\"\nproperty = \"v\"\n";
252	    const std::string p = stage_qemu_cfg(dir.string(), ok);
253	    CHECK(p == (dir / "qemu.cfg").string());
254	    {
255	      std::ifstream f(p);
256	      const std::string c((std::istreambuf_iterator<char>(f)),
257	                          std::istreambuf_iterator<char>());
258	      CHECK(c == ok.out);
259	    }
260	
261	    RunResult unknown_flag;  // engine without --print-qemu-config: parser throws
262	    unknown_flag.rc = 1;
263	    unknown_flag.out = "Unrecognized option: --print-qemu-config\n";
264	    CHECK(stage_qemu_cfg(dir.string(), unknown_flag).empty());
265	
266	    RunResult timed_out;
267	    timed_out.timed_out = true;
268	    CHECK(stage_qemu_cfg(dir.string(), timed_out).empty());
269	
270	    RunResult empty_out;  // exit 0 but nothing emitted -> nothing to load
271	    empty_out.rc = 0;
272	    CHECK(stage_qemu_cfg(dir.string(), empty_out).empty());
273	
274	    fs::remove_all(dir);
275	  }
276	
277	  // --- plan_argvs: a QEMU readconfig cfg is injected into the fast leg only ---
278	  // The engine's config.inc, distilled to a QEMU `-readconfig` cfg, makes the
279	  // QEMU producer match the accurate engine's ISA. Only the fast (QEMU) leg
280	  // gets `-readconfig <cfg>`; the vsim accurate leg never does. An empty cfg
281	  // injects nothing (fallback to the descriptor's default -cpu).
282	  {
283	    RuntimeCtx rcfg = rc;
284	    rcfg.qemu_cfg = "/wd/qemu.cfg";
285	    std::string err;
286	    std::vector<std::vector<std::string>> argvs =
287	        plan_argvs(plan, engines, "/wd", rcfg, err);
288	    CHECK(err.empty());
289	    CHECK(argvs.size() == 2);
290	    if (argvs.size() == 2) {
291	      bool fast_has = false;
292	      for (size_t k = 0; k + 1 < argvs[0].size(); ++k)
293	        if (argvs[0][k] == "-readconfig" && argvs[0][k + 1] == "/wd/qemu.cfg")
294	          fast_has = true;
295	      CHECK(fast_has);
296	      for (const std::string& a : argvs[1]) CHECK(a != "-readconfig");
297	    }
298	  }
299	  // empty qemu_cfg (the default rc) injects no -readconfig on either leg
300	  {
301	    std::string err;
302	    std::vector<std::vector<std::string>> argvs =
303	        plan_argvs(plan, engines, "/wd", rc, err);
304	    CHECK(err.empty());
305	    if (argvs.size() == 2)
306	      for (const std::vector<std::string>& a : argvs)
307	        for (const std::string& tok : a) CHECK(tok != "-readconfig");
308	  }
309	
310	  // --- leg_trigger_args: a trigger's per-role argv contribution ---
311	  {
312	    std::string err;
313	    // marker drives nothing into the argv; the plugin/vsim detect markers.
314	    LegTriggerArgs marker = leg_trigger_args({"marker", {}}, "fast-leg", err);
315	    CHECK(err.empty());
316	    CHECK(marker.plugin_suffix.empty());
317	    CHECK(marker.extra.empty());
318	
319	    // pc: qemu gets the enter_pc plugin suffix; vsim gets the exit-pc tokens.
320	    const Trigger pc = {"pc", {{"enter_pc", "0x10"}, {"exit_pc", "0x20"}}};
321	    LegTriggerArgs pf = leg_trigger_args(pc, "fast-leg", err);
322	    CHECK(err.empty());
323	    CHECK(pf.plugin_suffix == ",enter_pc=0x10");
324	    CHECK(pf.extra.empty());
325	    LegTriggerArgs pa = leg_trigger_args(pc, "accurate-leg", err);
326	    CHECK(err.empty());
327	    CHECK(pa.plugin_suffix.empty());
328	    check_eq(pa.extra, {"--hybrid-exit-pc", "0x20"}, "pc-acc");
329	
330	    // a role outside fast-leg/accurate-leg carries no trigger args
331	    LegTriggerArgs none = leg_trigger_args(pc, "standalone", err);
332	    CHECK(err.empty());
333	    CHECK(none.plugin_suffix.empty());
334	    CHECK(none.extra.empty());
335	
336	    // unknown trigger kind / missing required param are errors
337	    leg_trigger_args({"bogus", {}}, "fast-leg", err);
338	    CHECK(!err.empty());
339	    leg_trigger_args({"pc", {}}, "fast-leg", err);
340	    CHECK(!err.empty());
341	
342	    // verify oracle leg (verify_oracle F4): qemu drains at the ROI exit,
343	    // sampling at vsim's drained pc (drain_pc).
344	    const Trigger vm = {"verify-marker", {{"drain_pc", "0x100072"}}};
345	    LegTriggerArgs vmf = leg_trigger_args(vm, "fast-leg", err);
346	    CHECK(err.empty());
347	    CHECK(vmf.plugin_suffix == ",exit_marker=1,drain_pc=0x100072");
348	    CHECK(vmf.extra.empty());
349	    const Trigger vp = {"verify-pc",
350	                        {{"exit_pc", "0x20"}, {"drain_pc", "0x28"}}};
351	    LegTriggerArgs vpf = leg_trigger_args(vp, "fast-leg", err);
352	    CHECK(err.empty());
353	    CHECK(vpf.plugin_suffix == ",exit_pc=0x20,drain_pc=0x28");
354	    leg_trigger_args({"verify-marker", {}}, "fast-leg", err);
355	    CHECK(!err.empty());  // missing drain_pc
356	    leg_trigger_args({"verify-pc", {{"drain_pc", "0x28"}}}, "fast-leg", err);
357	    CHECK(!err.empty());  // missing exit_pc
358	  }
359	
360	  // --- plan_argvs: pc trigger threads enter_pc (qemu) + exit_pc (vsim) ---
361	  {
362	    Plan p = plan;
363	    const Trigger pc = {"pc", {{"enter_pc", "0x100000"}, {"exit_pc", "0x100042"}}};
364	    p.steps[0].trigger = pc;
365	    p.steps[1].trigger = pc;
366	    std::string err;
367	    std::vector<std::vector<std::string>> argvs =
368	        plan_argvs(p, engines, "/wd", rc, err);
369	    CHECK(err.empty());
370	    CHECK(argvs.size() == 2);
371	    if (argvs.size() == 2) {
372	      // qemu: enter_pc folded into the single -plugin token (its last arg)
373	      CHECK(argvs[0].back() == "/pl,outfile=/wd/state-0.bin,enter_pc=0x100000");
374	      // vsim: --hybrid-exit-pc appended verbatim after the filled template
375	      check_eq(argvs[1],
376	               {"/vbin", "/e", "--resume-from-qemu", "/wd/state-0.bin",
377	                "--handoff-out", "/wd/state-1.bin", "--shared-mem-path", "/mm",
378	                "--shared-mem-size", "134217728", "--shared-mem-base", "0x0",
379	                "--hybrid-exit-pc", "0x100042"},
380	               "pc-step1");
381	    }
382	  }
383	
384	  // --- plan_argvs: Step.extra_args append AFTER trigger args (e2e.sh order) ---
385	  {
386	    Plan p = plan;
387	    const Trigger pc = {"pc", {{"enter_pc", "0x100000"}, {"exit_pc", "0x100042"}}};
388	    p.steps[0].trigger = pc;
389	    p.steps[1].trigger = pc;
390	    p.steps[1].extra_args = {"--kanata", "k.txt"};
391	    std::string err;
392	    std::vector<std::vector<std::string>> argvs =
393	        plan_argvs(p, engines, "/wd", rc, err);
394	    CHECK(err.empty());
395	    if (argvs.size() == 2) {
396	      const std::vector<std::string>& v = argvs[1];
397	      CHECK(v.size() >= 4);
398	      // tail order: ... --hybrid-exit-pc 0x100042 --kanata k.txt
399	      CHECK(v[v.size() - 4] == "--hybrid-exit-pc");
400	      CHECK(v[v.size() - 3] == "0x100042");
401	      CHECK(v[v.size() - 2] == "--kanata");
402	      CHECK(v.back() == "k.txt");
403	    }
404	  }
405	
406	  // unknown engine id is an error
407	  {
408	    Plan bad = plan;
409	    bad.steps[0].engine_id = "nope";
410	    std::string err;
411	    CHECK(plan_argvs(bad, engines, "/wd", rc, err).empty());
412	    CHECK(!err.empty());
413	  }
414	  // a role the engine has no template for is an error
415	  {
416	    Plan bad = plan;
417	    bad.steps[1].role = "no-such-role";
418	    std::string err;
419	    CHECK(plan_argvs(bad, engines, "/wd", rc, err).empty());
420	    CHECK(!err.empty());
421	  }
422	
423	  // plan_step_rc_error: a drain leg that exits 0 ran the workload to completion
424	  // without ever reaching its ROI boundary -- the trigger never fired. The
425	  // message must say so and name the trigger kind, not just the bare
426	  // "expected exit 200, got 0" the user cannot act on.
427	  {
428	    const Step s{"qemu", "fast-leg", {"marker", {}}};
429	    const std::string m = plan_step_rc_error(0, s, 200, 0);
430	    CHECK(m.find("plan step 0") != std::string::npos);
431	    CHECK(m.find("marker") != std::string::npos);
432	    CHECK(m.find("without reaching") != std::string::npos);
433	  }
434	  // a genuine non-zero failure (engine crash, not a clean completion) keeps the
435	  // bare line -- no false "trigger never fired" claim.
436	  {
437	    const Step s{"qemu", "fast-leg", {"marker", {}}};
438	    const std::string m = plan_step_rc_error(1, s, 200, 139);
439	    CHECK(m.find("expected exit 200, got 139") != std::string::npos);
440	    CHECK(m.find("without reaching") == std::string::npos);
441	  }
442	
443	  return andes_sim::test::report("plan");
444	}
