// skip_memory_load: parse the ELF and set the reset vector, but leave
// platform.main_memory untouched. Used in tier-2 hybrid resume where
// QEMU 1's -kernel already populated the shared mmap; re-loading would
// zero-fill the .bss tail of each PT_LOAD and destroy phase-1 writes
// to static buffers. The reset vector is still set so the hart has a
// valid fetch target during the post-reset cycles that precede the DMI
// halt+DPC-write resume sequence.
void load_elf(const std::string& path, bool skip_memory_load = false)
{
  const auto elf = LIEF::ELF::Parser::parse(path);
  if (!elf) {
    spdlog::critical("Check if it's a valid ELF file path : {}", path);
    exit(1);
  }

  if (!skip_memory_load)
    read_elf_into_memory(
      *elf,
      static_cast<xlen_t>(platform.main_memory.region.base_address),
      platform.main_memory.data);
  for (auto& rv: platform.reset_vector)
    rv.write(elf->entrypoint());
}

void set_reset_vector(size_t hart, uint64_t addr)
{
  if (hart >= platform.reset_vector.size()) {
    spdlog::critical("hart {} out of range (max {})", hart,
                     platform.reset_vector.size() - 1);
    std::exit(EXIT_FAILURE);
  }
  platform.reset_vector[hart].write(addr);
}

// F5 (ROADMAP_ilm_dlm): dump the local memories' content next to the
// handoff-out state file -- the read duals of the --ilm/--dlm backdoor
// load, same "<state>.ilm/.dlm" sidecar convention as the QEMU plugin's
// entry drain. Zero sim cycles (hierarchical-reference read, ECC stripped).
// A wrapper without get_ilm/get_dlm dumps nothing.
void dump_lm_sidecars(const std::string& state_path)
{
  auto dump = [](const std::string& path, const std::vector<uint8_t>& data) {
    std::ofstream f(path, std::ios::binary | std::ios::trunc);
    f.write(reinterpret_cast<const char*>(data.data()),
            static_cast<std::streamsize>(data.size()));
    if (!f) throw std::runtime_error("cannot write " + path);
  };
  if constexpr (requires { cpu.get_ilm(); })
    dump(state_path + ".ilm", cpu.get_ilm());
  if constexpr (requires { cpu.get_dlm(); })
    dump(state_path + ".dlm", cpu.get_dlm());
}

void load_image(const std::string& path, MEM_TYPE type)
{
  switch (type) {
  case MEM_TYPE::ILM:
    if constexpr (requires { cpu.set_ilm({}); }) {
      read_binary_file(path, [this](const auto& data) { cpu.set_ilm(data); });
    } else {
      throw std::runtime_error(
        "CPU does not support ILM - cannot load ILM ROM image");
    }
    break;

  case MEM_TYPE::DLM:
    if constexpr (requires { cpu.set_dlm({}); }) {
      read_binary_file(path, [this](const auto& data) { cpu.set_dlm(data); });
    } else {
      throw std::runtime_error(
        "CPU does not support DLM - cannot load DLM ROM image");
    }
    break;

  case MEM_TYPE::RAM:
    read_binary_file(path, [this](const auto& data) {
      if (data.size() > platform.main_memory.data.size())
        throw std::runtime_error("RAM image size exceeds main memory size");
      std::copy(data.begin(), data.end(), platform.main_memory.data.begin());
    });
    break;

  default:
    throw std::runtime_error("Unknown memory type");
  }
}

void reset()
{
  static constexpr int core_num = CPU::NDS_NHART;
  static constexpr int reset_val = (1 << core_num) - 1;

  platform.resetn.write(0);
  auto saved = context_config;
  context_config = {};
  this->run(1);
  context_config = saved;

  for (size_t i = 0; i < platform.reset_vector.size(); ++i)
    spdlog::info("hart {} reset vector: {:#x}", i,
                 (uint64_t) platform.reset_vector[i].read());

  platform.resetn.write(reset_val);

  if (context_config.continue_from)
    restore_context(context_config.dir);
}

