// hybrid fast-forward leg (QEMU) runs the same ISA this engine models. The
// andesim driver captures this and passes it to QEMU via -readconfig; an engine
// built without a converter emits nothing, and the driver keeps its -cpu.
static void print_qemu_config()
{
  char* start = &_binary_qemu_cfg_start;
  char* end = &_binary_qemu_cfg_end;
  fwrite(start, 1, end - start, stdout);
}

// Emit the andes-sim engine descriptor (see docs/engine_interface.md). This is
// the self-describe half of the framework's hot-plug contract: andes-sim runs
// `sim_<cfg> --describe`, parses this JSON, and can then drive the binary with
// no per-engine code. vlen/xlen come from the same embedded config.inc blob
// that --print-config dumps; the config name comes from VSIM_CPU_PYMODULE_NAME.
// Whether a cpu wrapper implements the set_ilm/set_dlm backdoor. Variable
// templates so the requires-expression sits in a DEPENDENT context: a wrapper
// without the member then SFINAEs to false, where the same expression written
// non-dependently (e.g. inline in a plain lambda) is a HARD compile error on
// such a wrapper (ax46mpv today).
template <typename CPU>
inline constexpr bool kCpuCanLoadIlm = requires(CPU& c) { c.set_ilm({}); };
template <typename CPU>
inline constexpr bool kCpuCanLoadDlm = requires(CPU& c) { c.set_dlm({}); };

// can_load_ilm/can_load_dlm: whether THIS binary's cpu wrapper implements the
// set_ilm/set_dlm backdoor. The descriptor's ilm_size/dlm_size mean "LM
// content transport supported at this size" -- the andesim driver passes
// --ilm/--dlm whenever they are > 0, and load_image throws on a wrapper
// without the backdoor -- so an engine that cannot load must report 0 even
// when its config.inc has the memory (e.g. ax46mpv_advanced today).
static void describe_engine(bool can_load_ilm, bool can_load_dlm)
{
  std::string cfg = VSIM_CPU_PYMODULE_NAME;  // "simulator_<cfg>"
  const std::string prefix = "simulator_";
  if (cfg.starts_with(prefix))
    cfg = cfg.substr(prefix.size());

  const std::string_view blob(&_binary_config_inc_start,
                              static_cast<size_t>(&_binary_config_inc_end
                                                  - &_binary_config_inc_start));
  auto scan_int = [blob](std::string_view key) -> long {
    size_t pos = blob.find(key);
    if (pos == std::string_view::npos)
      return 0;
    pos += key.size();
    while (pos < blob.size() && (blob[pos] < '0' || blob[pos] > '9'))
      ++pos;
    long v = 0;
    while (pos < blob.size() && blob[pos] >= '0' && blob[pos] <= '9')
      v = v * 10 + (blob[pos++] - '0');
    return v;
  };
  const long vlen = scan_int("NDS_VLEN");
  const long dlen = scan_int("NDS_DLEN");
  const long elen = scan_int("NDS_ELEN");
  const long xlen = scan_int("NDS_XLEN");
  // Hart-0 local memories, reported in BYTES (the config macro is KB). 0 =
  // this engine has none OR cannot backdoor-load it; either way the driver
  // arms no LM content transport.
  const long ilm_size = can_load_ilm ? scan_int("NDS_ILM_SIZE_KB") * 1024 : 0;
  const long dlm_size = can_load_dlm ? scan_int("NDS_DLM_SIZE_KB") * 1024 : 0;

  // Built by hand (not fmt) to keep the literal {bin}/{elf}/{state_in}
  // placeholders out of fmt's brace parser.
  std::string json;
  json += "{\n";
  json += "  \"id\": \"verilator:" + cfg + "\",\n";
  json += "  \"type\": \"verilator\",\n";
  json += "  \"kind\": \"cycle-accurate\",\n";
  json += "  \"vlen\": " + std::to_string(vlen) + ", \"dlen\": "
          + std::to_string(dlen) + ", \"elen\": " + std::to_string(elen)
          + ", \"xlen\": " + std::to_string(xlen) + ",\n";
  json += "  \"ilm_size\": " + std::to_string(ilm_size) + ", \"dlm_size\": "
          + std::to_string(dlm_size) + ",\n";
  json += "  \"triggers\": [\"csr\", \"pc\"],\n";
  json += "  \"roles\": [\"standalone\", \"accurate-leg\"],\n";
  json += "  \"state\": [\"resume\", \"drain\"],\n";
  // Andes custom CSRs this core actually implements (from its config.inc).
  // The driver uses this to skip --verify on CSRs the engine lacks, mirroring
  // the resume/drain gating in ResumeDriver/StateDrain (single binder).
  const std::vector<std::string> andes_csrs =
      hybrid::supported_andes_csr_names(hybrid::andes_caps_from_config());
  json += "  \"andes_csrs\": [";
  for (size_t i = 0; i < andes_csrs.size(); ++i)
    json += (i ? ", \"" : "\"") + andes_csrs[i] + "\"";
  json += "],\n";
  json += "  \"invoke\": {\n";
  json += "    \"standalone\": [\"{bin}\", \"{elf}\"],\n";
  json += "    \"accurate-leg\": [\"{bin}\", \"{elf}\", "
          "\"--resume-from-qemu\", \"{state_in}\", "
          "\"--handoff-out\", \"{state_out}\", "
          "\"--shared-mem-path\", \"{mmap}\", "
          "\"--shared-mem-size\", \"{mmap_size}\", "
          "\"--shared-mem-base\", \"{mmap_base}\"]\n";
  json += "  },\n";
  json += "  \"result\": \"stderr:cycles\"\n";
  json += "}\n";
  fwrite(json.data(), 1, json.size(), stdout);
}

